tasks.solution:
CREATE TABLE sat_customer AS
SELECT md5(CAST(customer_id AS VARCHAR)) AS customer_hk, city,
       TIMESTAMP '2026-07-01 03:00:00' AS load_date
FROM customers;

INSERT INTO sat_customer VALUES (md5('1042'), 'Москва', TIMESTAMP '2026-07-02 03:00:00');

SELECT arg_max(city, load_date) AS city, COUNT(*) AS versions
FROM sat_customer
WHERE customer_hk = md5('1042');
